def valid_date(date):
    # Check if the date string is not empty and in the format mm-dd-yyyy
    if not date or len(date.split('-')) != 3:
        return False

    month, day, year = date.split('-')

    # Check if the month is between 1 and 12
    if not month.isdigit() or not (1 <= int(month) <= 12):
        return False

    # Check if the day is a valid day for the given month
    if not day.isdigit():
        return False

    day = int(day)

    if month == '02':
        # February can have 29 days at most
        if not (1 <= day <= 29):
            return False
    elif month in ['04', '06', '09', '11']:
        # April, June, September, November can have 30 days
        if not (1 <= day <= 30):
            return False
    elif month in ['01', '03', '05', '07', '08', '10', '12']:
        # January, March, May, July, August, October, December can have 31 days
        if not (1 <= day <= 31):
            return False

    # Check if the year is a 4-digit number
    if not year.isdigit() or len(year) != 4:
        return False

    return True

# Test cases
print(valid_date('03-11-2000'))  # Expected output: True
print(valid_date('15-01-2012'))  # Expected output: False
print(valid_date('04-0-2040'))  # Expected output: False
print(valid_date('06-04-2020'))  # Expected output: True
print(valid_date('06/04/2020'))  # Expected output: False
